#: URL des notifications de rapport envoyées avant `WeeklyReportSent` (`/parent/enfants/<id>/rapport?semaine=<semaine>`)
REPORT_URL = re.compile(r"^/parent/enfants/(\d+)/rapport\?semaine=(\d{4}-W\d{2})$")


def reserve_sent_reports(apps, schema_editor):
    """Rapports déjà notifiés : réservés, pour que la semaine du déploiement ne les renvoie pas."""
    Notification = apps.get_model("notifications", "Notification")
    WeeklyReportSent = apps.get_model("accounts", "WeeklyReportSent")
    User = apps.get_model("accounts", "User")
    sent = Notification.objects.filter(type="weekly_report").values_list("user_id", "url")
    for parent_id, url in sent:
        match = REPORT_URL.match(url)
        if match and User.objects.filter(pk=match[1]).exists():
            WeeklyReportSent.objects.get_or_create(
                parent_id=parent_id, child_id=int(match[1]), week=match[2]
            )


